// Animated figure library for the guided stretch player.
//
// Routines are generated by the coach, so the drill names are free-form — we
// can never guarantee a hand-drawn illustration for whatever it invents. So
// this file defines a CLOSED set of poses and three ways to land on one:
//
//   1. The coach emits a `pose` slug from the enum below (the reliable path —
//      the enum is listed verbatim in the trainer prompt).
//   2. Failing that, keyword-match the drill's name (KEYWORDS).
//   3. Failing that, fall back to a generic figure for the item's modality,
//      so EVERY step still shows something moving.
//
// A pose is pure geometry: joint coordinates in a 120x100 viewBox with the
// floor at y=92, plus optional props and a motion hint. Two frames means a
// two-beat loop (the player cross-fades them); one frame means a still figure
// animated by `motion` / `swing` / `spin`. Keeping this as data — not JSX —
// means components/StretchFigure.tsx is the single renderer and adding a drill
// is a dozen lines here.

export type Pt = [number, number];

// shoulder/hip → elbow/knee → hand/foot
type Limb = [Pt, Pt, Pt];

export type PoseFrame = {
  head: Pt;
  headR?: number;
  neck: Pt;
  hip: Pt;
  // Control point making the spine a quadratic curve instead of a straight
  // line — what lets cat/cow arch and round, and child's pose fold over.
  spineCtl?: Pt;
  armA?: Limb;
  armB?: Limb;
  legA?: Limb;
  legB?: Limb;
};

export type PoseProp =
  | { kind: "floor" }
  | { kind: "wall"; x: number }
  | { kind: "roller"; at: Pt; r?: number }
  // A bar drawn between the two hands of whichever frame is showing.
  | { kind: "handbar" };

export type PoseDef = {
  frames: [PoseFrame] | [PoseFrame, PoseFrame];
  props?: PoseProp[];
  // Whole-figure idle motion. "breathe" is the default resting animation for a
  // static hold; "roll" slides the body along a foam roller.
  motion?: "breathe" | "sway" | "roll";
  // Limbs that rotate continuously (arm circles) or swing back and forth
  // (leg swings), pivoting on their first joint.
  spin?: ("armA" | "armB")[];
  swing?: ("legA" | "legB")[];
};

