// Name keywords → pose, for when the coach names a drill but omits the slug.
// Order matters: the FIRST entry whose keyword appears in the lowercased name
// wins, so the more specific phrases come first ("foam roll quad" must beat a
// bare "quad").
const KEYWORDS: [string[], StretchPose][] = [
  // soft tissue first — these names usually also contain a muscle word that a
  // later static-stretch rule would otherwise claim.
  [["it band", "itband", "iliotibial", "tfl", "outer thigh"], "foamroll-itband"],
  [["thoracic roll", "upper back roll", "t-spine roll", "roll your back", "back roll"], "foamroll-back"],
  [["glute ball", "lacrosse", "tennis ball", "glute smash", "piriformis release"], "ball-glute"],
  // breathing
  [["box breath", "breathing", "breathe", "breath work", "breathwork", "diaphragm"], "breathing-supine"],
  // dynamic
  [["cat-cow", "cat cow", "cat camel"], "cat-cow"],
  [["world's greatest", "worlds greatest", "spiderman"], "worlds-greatest"],
  [["leg swing", "leg swings"], "leg-swing"],
  [["arm circle", "shoulder circle"], "arm-circles"],
  [["hip car", "hip circle", "hip cars", "90/90 switch", "knee circle"], "hip-cars"],
  [["open book", "thoracic rotation", "t-spine rotation", "windmill"], "open-book"],
  [["deep squat", "squat hold", "malasana", "third world squat", "cossack"], "deep-squat"],
  [["glute bridge", "hip bridge", "bridge"], "glute-bridge"],
  [["pass-through", "pass through", "shoulder dislocate", "band dislocate"], "shoulder-pass-through"],
  [["hang", "dead hang", "bar hang"], "bar-hang"],
  [["crab", "reverse plank", "table top", "tabletop"], "crab-bridge"],
  [["down dog", "downward dog", "down-dog", "adho mukha"], "down-dog"],
  [["bretzel"], "bretzel"],
  [["90/90", "90-90", "ninety"], "ninety-ninety"],
  [["butcher"], "butchers-block"],
  [["crawl"], "crawl"],
  // static
  [["figure-4", "figure 4", "figure four"], "figure-4"],
  [["pigeon", "90/90", "lizard"], "pigeon"],
  [["child", "balasana"], "child-pose"],
  [["couch stretch", "hip flexor", "kneeling lunge", "quad stretch", "psoas"], "hip-flexor-lunge"],
  [["doorway", "pec ", "pectoral", "chest stretch", "chest opener"], "chest-doorway"],
  [["tricep", "lat stretch overhead", "overhead reach"], "overhead-triceps"],
  [["neck", "upper trap", "levator", "scalene"], "neck-lateral"],
  [["calf", "gastroc", "soleus", "achilles", "ankle dorsiflex"], "calf-wall"],
  [["butterfly", "adductor", "groin", "straddle", "frog"], "butterfly"],
  [["seated twist", "spinal twist", "twist"], "seated-twist"],
  [["supine twist", "lying twist", "scorpion"], "supine-twist"],
  [["cobra", "sphinx", "extension", "press-up", "mckenzie"], "cobra"],
  [["side bend", "lat stretch", "lat ", "side body", "quadratus", "qL "], "side-bend"],
  [["hamstring", "toe touch", "forward fold", "pike", "good morning stretch"], "hamstring-hinge"],
  // muscle-only names that still imply a roller when paired with roll words
  [["quad"], "foamroll-quad"],
  [["glute", "hip stretch", "piriformis"], "figure-4"],
];

const ROLL_WORDS = ["foam roll", "foam-roll", "roller", "roll ", "smr", "release", "smash"];

const GENERIC: Record<string, StretchPose> = {
  static: "generic-static",
  dynamic: "generic-dynamic",
  // Loaded work is movement under load — the dynamic figure reads closer than
  // a passive hold when no specific pose matches.
  loaded: "generic-dynamic",
  foamroll: "generic-foamroll",
  breathing: "generic-breathing",
};

// Roller variants keyed by the muscle a rolling drill names, so "foam roll
// your hamstrings" lands on the seated roller figure rather than the standing
// hamstring stretch.
const ROLL_TARGETS: [string[], StretchPose][] = [
  [["hamstring"], "foamroll-hamstring"],
  [["quad", "thigh", "hip flexor"], "foamroll-quad"],
  [["it band", "itband", "outer"], "foamroll-itband"],
  [["calf", "gastroc", "soleus"], "foamroll-calf"],
  [["back", "thoracic", "t-spine", "lat"], "foamroll-back"],
  [["glute", "piriformis", "hip"], "ball-glute"],
];

export function isStretchPose(v: unknown): v is StretchPose {
  return typeof v === "string" && POSE_SET.has(v);
}

// Normalize whatever the model put in `pose` (case/spacing/underscore drift)
// onto a known slug, or null if it isn't one of ours.
export function coercePose(v: unknown): StretchPose | null {
  if (typeof v !== "string") return null;
  const k = v.trim().toLowerCase().replace(/[\s_]+/g, "-");
  return POSE_SET.has(k) ? (k as StretchPose) : null;
}

// The whole resolution chain: explicit slug → name keywords → modality
// fallback. Always returns a renderable pose so no step is ever blank.
export function resolvePose(
  pose: StretchPose | null | undefined,
  name: string,
  kind: string | null | undefined,
): StretchPose {
  if (pose && POSE_SET.has(pose)) return pose;

  const n = (name || "").toLowerCase();

  // A rolling/release drill: pick the roller figure for whatever it targets.
  if (ROLL_WORDS.some((w) => n.includes(w)) || kind === "foamroll") {
    for (const [words, p] of ROLL_TARGETS) {
      if (words.some((w) => n.includes(w))) return p;
    }
  }

  for (const [words, p] of KEYWORDS) {
    if (words.some((w) => n.includes(w))) return p;
  }

  return GENERIC[kind ?? "static"] ?? "generic-static";
}
